CREATE TABLE IF NOT EXISTS channels (id text PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS contacts (id text PRIMARY KEY, channel_id text NOT NULL REFERENCES channels(id), line_user_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(channel_id,line_user_id));
CREATE TABLE IF NOT EXISTS conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), contact_id text NOT NULL REFERENCES contacts(id), mode text NOT NULL DEFAULT 'AI' CHECK(mode IN ('AI','HUMAN')), status text NOT NULL DEFAULT 'OPEN', updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(contact_id));
CREATE TABLE IF NOT EXISTS messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES conversations(id), direction text NOT NULL, sender text NOT NULL, content text NOT NULL, line_message_id text UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS messages_conversation_idx ON messages(conversation_id,created_at DESC);
CREATE TABLE IF NOT EXISTS webhook_events (event_id text PRIMARY KEY, payload jsonb NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), claimed_at timestamptz, attempts integer NOT NULL DEFAULT 0, processed_at timestamptz, error text);
CREATE TABLE IF NOT EXISTS summaries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES conversations(id), body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS support_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES conversations(id), summary text NOT NULL, status text NOT NULL DEFAULT 'OPEN', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dedupe_key text NOT NULL UNIQUE, target_user_id text NOT NULL, channel_id text NOT NULL, body text NOT NULL, status text NOT NULL DEFAULT 'PENDING', attempts integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), sent_at timestamptz);
CREATE TABLE IF NOT EXISTS audit_logs (id bigserial PRIMARY KEY, actor text NOT NULL, action text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
